function transactions(){return db.prepare(`SELECT * FROM economy_tx WHERE character_id='char-demo' ORDER BY created_at DESC LIMIT 50`).all().map(t=>({id:t.id,kind:t.kind,goldDelta:t.gold_delta,cityId:t.city_id,goodTypeId:t.good_id,quantity:t.quantity,createdAt:new Date(t.created_at).toISOString()}))}
const battleRows=id=>db.prepare(`SELECT * FROM battle_units WHERE battle_id=? ORDER BY side DESC,id`).all(id);
const battleDistance=(a,b)=>Math.max(Math.abs(a.row_no-b.row_no),Math.abs(a.col_no-b.col_no));
const pointDistance=(a,b)=>Math.max(Math.abs((a.row_no??a.row)-(b.row_no??b.row)),Math.abs((a.col_no??a.col)-(b.col_no??b.col)));
function nearestOpenCell(row,col,units,reserved=new Set(),excludeId=''){const occupied=new Set(units.filter(x=>x.alive&&x.id!==excludeId&&x.dest_row==null).map(x=>`${x.row_no}:${x.col_no}`)),cells=[];for(let r=0;r<5;r++)for(let c=0;c<60;c++)if(!occupied.has(`${r}:${c}`)&&!reserved.has(`${r}:${c}`))cells.push({row:r,col:c});return cells.sort((a,b)=>pointDistance(a,{row,col})-pointDistance(b,{row,col})||Math.abs(a.col-col)-Math.abs(b.col-col)||a.row-b.row||a.col-b.col)[0]}
function approachCell(unit,target,units,reserved,ideal){const occupied=new Set(units.filter(x=>x.alive&&x.id!==unit.id&&x.dest_row==null).map(x=>`${x.row_no}:${x.col_no}`)),cells=[];for(let row=0;row<5;row++)for(let col=0;col<60;col++){const key=`${row}:${col}`,range=pointDistance({row,col},target);if(range>0&&range<=unit.attack_range&&!occupied.has(key)&&!reserved.has(key))cells.push({row,col})}return cells.sort((a,b)=>(ideal?pointDistance(a,ideal)-pointDistance(b,ideal):0)||pointDistance(unit,a)-pointDistance(unit,b)||pointDistance(a,target)-pointDistance(b,target)||Math.abs(a.row-unit.row_no)-Math.abs(b.row-unit.row_no)||a.row-b.row)[0]}
const skillDefinitions={hero:[{id:'heavy-strike',name:'重擊',damage:32,range:2,cooldownMs:4000,type:'NORMAL',targetType:'ENEMY'},{id:'thunder-rune',name:'雷擊符',damage:45,range:7,cooldownMs:10000,type:'SPECIAL',targetType:'ENEMY',requiresRune:'Z',description:'畫出 Z 符後，對鎖定敵人造成 45 傷害'},{id:'heaven-rune',name:'天雷陣',damage:35,cooldownMs:20000,type:'ULTIMATE',targetType:'SELF',requiresRune:'O',areaAllEnemies:true,description:'畫出 O 符；畫符期間全場暫停，完成後攻擊所有敵人',resultText:'天雷擊中全體敵人'},{id:'tactical-pause',name:'戰術暫停',cooldownMs:12000,durationMs:10000,effectId:'tactical-pause',effectValue:1,effectScope:'ENEMIES',type:'TACTICAL',targetType:'SELF',description:'全體敵人暫停最多 10 秒 · 任一敵人受傷即全體解除',resultText:'全體敵人暫停，受擊即解除'}],archer:[{id:'heartseeker-arrow',name:'穿心箭',damage:24,range:7,cooldownMs:5000,type:'NORMAL',targetType:'ENEMY'},{id:'slow-arrow',name:'緩速箭',damage:8,range:7,cooldownMs:8000,durationMs:4000,effectId:'slowed',effectValue:.5,type:'TACTICAL',targetType:'ENEMY',description:'目標移動速度減半 · 4 秒',resultText:'造成 8 傷害並緩速 4 秒'},{id:'arrow-rain',name:'箭雨',damage:18,range:7,radius:1,cooldownMs:8000,type:'NORMAL',targetType:'CELL',description:'選擇落點 · 半徑 1 格 · 18 傷害'}],guard:[{id:'iron-wall',name:'鐵壁',cooldownMs:10000,durationMs:5000,reduction:.5,type:'NORMAL',targetType:'SELF',description:'所受傷害減半 · 5 秒'},{id:'ice-wall',name:'冰牆',range:6,width:2,cooldownMs:12000,durationMs:15000,createsIceWall:true,type:'TACTICAL',targetType:'CELL',description:'建立橫跨 5 行、厚 2 列冰牆 · 雙方不能穿越 · 15 秒',resultText:'建立 5×2 冰牆'}]};
const playerTemplates=[{id:'hero',name:'主角',role:'MELEE',row:2,col:2,baseHp:120,hpPerLevel:12,baseAttack:18,attackPerLevel:2,range:2,interval:900,agility:10,moveInterval:450},{id:'archer',name:'弓手',role:'RANGED',row:1,col:1,baseHp:80,hpPerLevel:8,baseAttack:13,attackPerLevel:2,range:5,interval:750,agility:14,moveInterval:300},{id:'guard',name:'護衛',role:'MELEE',row:3,col:1,baseHp:105,hpPerLevel:15,baseAttack:15,attackPerLevel:1,range:2,interval:1000,agility:8,moveInterval:600}];
